E=[('transform:scaleX(1.45)','Não distorça'),('transform:rotate(-12deg)','Não gire'),('filter:hue-rotate(150deg)','Não troque as cores'),('filter:drop-shadow(6px 6px 4px rgba(0,0,0,.6))','Não aplique sombra'),('','Não use em fundo sem contraste','#F2B000'),('opacity:.35','Não aplique transparência'),('filter:blur(1.2px)','Não use arquivo de baixa qualidade'),('','Não recrie o texto em outra fonte','#fff','fonte')]
def errado(e):
    st,t=e[0],e[1]; bg=e[2] if len(e)>2 else '#fff'
    inner='<div style="font:400 40px Georgia;color:#024E25">Coração<span style="color:#FFBC04">BR</span></div>' if len(e)>3 else logo('coracaobr-logo','270px',st)
    return '<div><div style="background:%s;border:1px solid #E4E2DA;border-radius:12px;height:205px;display:grid;place-items:center;position:relative;overflow:hidden">%s<span style="position:absolute;right:10px;top:8px;width:30px;height:30px;border-radius:50%%;background:#D93025;color:#fff;font:700 18px/30px Outfit;text-align:center">×</span></div><p class="sm" style="margin-top:10px"><b>%s</b></p></div>'%(bg,inner,t)
P.append('<section class="pg ar"><div class="ey">O logo</div><h2>Usos incorretos</h2><div class="g4" style="gap:22px;margin-top:20px">'+''.join(errado(e) for e in E)+'</div><p class="mu sm" style="margin-top:22px">Use sempre os arquivos oficiais entregues com este manual. Na dúvida, prefira a versão principal sobre fundo branco.</p>'+ft(S,13)+'</section>')
