perfil='''<div style="display:flex;flex-direction:column;align-items:center;gap:12px;width:220px"><div style="width:150px;height:150px;border-radius:50%%;background:#024E25;display:grid;place-items:center;box-shadow:0 8px 24px rgba(0,0,0,.15)">%s</div><b style="font:700 18px Outfit">coracaobr</b><p class="xs mu" style="text-align:center">Avatar em redes sociais e WhatsApp Business: ícone verde, recorte circular.</p></div>'''%logo('coracaobr-simbolo','104px')
P.append('<section class="pg ar"><div class="ey">Aplicações</div><h2>Redes sociais</h2><div style="display:flex;gap:40px;align-items:flex-start;margin-top:10px">'+post+story+perfil+'</div><p class="mu sm" style="margin-top:20px">Fotos reais do lugar ou evento, faixa em degradê Verde Floresta, título em Outfit Bold e etiqueta amarela de categoria. Exemplos ilustrativos com dados reais do mercado de lançamento.</p>'+ft(S,18)+'</section>')
# 19 papelaria
cartao_f='<div style="width:630px;height:360px;border-radius:12px;background:#fff;box-shadow:0 14px 40px rgba(0,0,0,.14);display:grid;place-items:center">%s</div>'%logo('coracaobr-logo','440px')
cartao_v='<div style="width:630px;height:360px;border-radius:12px;background:var(--vf);color:#fff;box-shadow:0 14px 40px rgba(0,0,0,.14);padding:40px;display:flex;flex-direction:column;justify-content:space-between"><div style="display:flex;justify-content:space-between;align-items:start"><div><div style="font:700 26px Outfit">Nome Sobrenome</div><div style="opacity:.7;font-size:15px">Parcerias comerciais</div></div>%s</div><div style="font-size:15px;line-height:1.7;opacity:.9">contato@[dominio]<br>WhatsApp +1 (000) 000-0000<br>[Cidade, País]</div></div>'%logo('coracaobr-simbolo','70px')
