vit='<div style="width:640px;height:400px;border-radius:14px;background:linear-gradient(180deg,#9DB3B0,#5E7774);position:relative;overflow:hidden"><div style="position:absolute;left:40px;right:40px;top:40px;bottom:0;background:linear-gradient(135deg,rgba(255,255,255,.35),rgba(255,255,255,.05));border:8px solid #2B2F2E;border-bottom:none"></div><div style="position:absolute;left:70px;top:70px;transform:scale(.48);transform-origin:0 0">'+selo+'</div><div style="position:absolute;right:70px;top:90px;font:700 44px Outfit;color:#fff;opacity:.92">OPEN</div></div>'
