b2='<div style="width:728px;height:90px;border-radius:10px;background:var(--vf);display:flex;align-items:center;gap:26px;padding:0 26px;color:#fff">%s<div style="flex:1;font:600 20px Outfit">Seu negócio na frente da comunidade brasileira</div><div style="background:#FFBC04;color:var(--vf);font:700 15px Outfit;padding:10px 18px;border-radius:99px">Anuncie por US$ 10/mês</div></div>'%logo('coracaobr-logo-negativo','180px')
P.append('<section class="pg"><div class="ey">Aplicações</div><h2>Anúncios e banners</h2><div style="display:grid;gap:40px;margin-top:20px"><div style="display:flex;gap:40px;align-items:flex-end">'+b1+'<div><p class="sm"><b>300 × 250</b> · card de anunciante dentro do app, sempre com a palavra "Patrocinado".</p></div></div><div>'+b2+'<p class="sm" style="margin-top:12px"><b>728 × 90</b> · banner de captação de anunciantes em sites parceiros.</p></div></div>'+ft(S,21)+'</section>')
# 22 arquivos
A=[('SVG','Vetorial. Site, app e qualquer ampliação.','logo, negativo, mono verde, mono branco, símbolo, ícone, ícone verde'),('PNG','Fundo transparente. Redes, documentos, apresentações.','logo e negativo em 600, 1200, 2400 e 4800 px; mono em 1200 e 2400 px; símbolo de 256 a 2048 px; ícones de 180 a 1024 px'),('PDF','Vetorial. Gráfica e impressão.','uma página por versão, com margem de proteção')]
P.append('<section class="pg vf"><div class="ey">Arquivos</div><h2>O que foi entregue</h2><div class="g3" style="margin-top:20px">'+''.join('<div class="card"><div style="font:800 46px Outfit;color:#FFBC04">%s</div><h3 style="margin-top:8px">%s</h3><p class="mu sm" style="margin-top:8px">%s</p></div>'%a for a in A)+'</div><div style="margin-top:46px;display:flex;justify-content:space-between;align-items:end"><div><p class="mu sm">Pasta <b style="color:#fff">coracaobr-marca</b>: svg/, png/, pdf/, Manual da marca, Mídia kit e Apresentação.</p><p class="mu sm" style="margin-top:6px">Dúvidas sobre uso da marca: equipe CoraçãoBR, pelo contato da página Sobre.</p></div>'+logo('coracaobr-logo-negativo','360px')+'</div>'+ft(S,22)+'</section>')
